CREATE TABLE orders(id UUID PRIMARY KEY,customer_id UUID NOT NULL,customer_email VARCHAR(255) NOT NULL,order_code VARCHAR(60) NOT NULL UNIQUE,total_amount NUMERIC(18,2) NOT NULL CHECK(total_amount>=0),currency VARCHAR(3) NOT NULL,payment_method VARCHAR(20) NOT NULL CHECK(payment_method IN ('COD','ONLINE')),status VARCHAR(30) NOT NULL CHECK(status IN ('PENDING','RESERVED','PAID','CONFIRMED','SHIPPING','COMPLETED','CANCELLED')),shipping_address JSONB NOT NULL,idempotency_key VARCHAR(128) NOT NULL,request_hash VARCHAR(64) NOT NULL,stock_committed BOOLEAN NOT NULL DEFAULT false,version BIGINT NOT NULL,created_at TIMESTAMPTZ NOT NULL,updated_at TIMESTAMPTZ NOT NULL,UNIQUE(customer_id,idempotency_key));
CREATE INDEX idx_orders_customer_date ON orders(customer_id,created_at DESC);
CREATE INDEX idx_orders_status_date ON orders(status,created_at);
CREATE TABLE order_items(order_id UUID NOT NULL REFERENCES orders(id),line_number INTEGER NOT NULL,product_id VARCHAR(100) NOT NULL,sku VARCHAR(100) NOT NULL,product_name VARCHAR(255) NOT NULL,unit_price NUMERIC(18,2) NOT NULL CHECK(unit_price>=0),quantity INTEGER NOT NULL CHECK(quantity>0),subtotal NUMERIC(18,2) NOT NULL CHECK(subtotal=unit_price*quantity),PRIMARY KEY(order_id,line_number));
CREATE TABLE order_status_history(order_id UUID NOT NULL REFERENCES orders(id),entry_number INTEGER NOT NULL,old_status VARCHAR(30),new_status VARCHAR(30) NOT NULL,reason TEXT,changed_at TIMESTAMPTZ NOT NULL,PRIMARY KEY(order_id,entry_number));
CREATE TABLE carts(id UUID PRIMARY KEY,customer_id UUID NOT NULL UNIQUE);
CREATE TABLE cart_items(id UUID PRIMARY KEY,cart_id UUID NOT NULL REFERENCES carts(id) ON DELETE CASCADE,product_id VARCHAR(100) NOT NULL,sku VARCHAR(100) NOT NULL,quantity INTEGER NOT NULL CHECK(quantity BETWEEN 1 AND 10000),UNIQUE(cart_id,sku));
